pub fn lbVector_Mirror<'a>(ctx: &'a Ctx, a: Vec<'a>, unit_mirror_axis: Vec<'a>) {
    let mut a = a;
    let mut unit_mirror_axis = unit_mirror_axis;
    let mut f: f64 = fp::fmuls(
        fp::fneg(2.0),
        (fp::fmadds(
            (unit_mirror_axis).x(),
            (a).x(),
            fp::fmuls((unit_mirror_axis).y(), (a).y()),
        )),
    );
    (a).set_x(fp::fmadds((unit_mirror_axis).x(), f, (a).x()));
    (a).set_y(fp::fmadds((unit_mirror_axis).y(), f, (a).y()));
}

pub fn lbVector_CosAngle<'a>(ctx: &'a Ctx, a: Vec<'a>, b: Vec<'a>) -> f64 {
    let __frame = ctx.stack_frame(0x18);
    let mut a = a;
    let mut b = b;
    return {
        let __t2 = ({
            let __t1 = inl_sqrtf(
                ctx,
                fp::fadds(fp::fmuls((b).x(), (b).x()), fp::fmuls((b).y(), (b).y())),
            );
            fp::fmuls(
                inl_sqrtf(
                    ctx,
                    fp::fadds(fp::fmuls((a).x(), (a).x()), fp::fmuls((a).y(), (a).y())),
                ),
                __t1,
            )
        });
        fp::fdivs(
            (fp::fmadds((a).x(), (b).x(), fp::fmuls((a).y(), (b).y()))),
            __t2,
        )
    };
}

pub fn lbVector_Lerp<'a>(ctx: &'a Ctx, a: Vec<'a>, b: Vec<'a>, result: Vec<'a>, f: f64) -> Vec<'a> {
    let mut a = a;
    let mut b = b;
    let mut result = result;
    let mut f = f;
    let _ = inl_lbVector_Diff_unfused(ctx, b, a, result);
    (result).set_x(fp::fmuls((result).x(), f));
    (result).set_y(fp::fmuls((result).y(), f));
    (result).set_z(fp::fmuls((result).z(), f));
    let _ = inl_lbVector_Add_unfused(ctx, result, a);
    return result;
}

pub fn lbVector_8000DE38<'a>(ctx: &'a Ctx, points: Vec<'a>, v: Vec<'a>, c: f64) -> Vec<'a> {
    let mut points = points;
    let mut v = v;
    let mut c = c;
    let mut var1: f64 = 0.0;
    let mut var2: f64 = 0.0;
    if c > 1.0 {
        c = 1.0;
    } else if c < 0.0 {
        c = 0.0;
    }
    var1 = fp::fmadds(
        2.0,
        (Handle::add(points, 2_i32)).x(),
        fp::fmsubs(
            2.0,
            (Handle::add(points, 0_i32)).x(),
            fp::fmuls(4.0, (Handle::add(points, 1_i32)).x()),
        ),
    );
    var2 = fp::fsubs(
        fp::fmadds(
            fp::fneg(3.0),
            (Handle::add(points, 0_i32)).x(),
            fp::fmuls(4.0, (Handle::add(points, 1_i32)).x()),
        ),
        (Handle::add(points, 2_i32)).x(),
    );
    (v).set_x(fp::fadds(
        (Handle::add(points, 0_i32)).x(),
        (fp::fmadds(c, fp::fmuls(var1, c), fp::fmuls(var2, c))),
    ));
    var1 = fp::fmadds(
        2.0,
        (Handle::add(points, 2_i32)).y(),
        fp::fmsubs(
            2.0,
            (Handle::add(points, 0_i32)).y(),
            fp::fmuls(4.0, (Handle::add(points, 1_i32)).y()),
        ),
    );
    var2 = fp::fsubs(
        fp::fmadds(
            fp::fneg(3.0),
            (Handle::add(points, 0_i32)).y(),
            fp::fmuls(4.0, (Handle::add(points, 1_i32)).y()),
        ),
        (Handle::add(points, 2_i32)).y(),
    );
    (v).set_y(fp::fadds(
        (Handle::add(points, 0_i32)).y(),
        (fp::fmadds(c, fp::fmuls(var1, c), fp::fmuls(var2, c))),
    ));
    var1 = fp::fmadds(
        2.0,
        (Handle::add(points, 2_i32)).z(),
        fp::fmsubs(
            2.0,
            (Handle::add(points, 0_i32)).z(),
            fp::fmuls(4.0, (Handle::add(points, 1_i32)).z()),
        ),
    );
    var2 = fp::fsubs(
        fp::fmadds(
            fp::fneg(3.0),
            (Handle::add(points, 0_i32)).z(),
            fp::fmuls(4.0, (Handle::add(points, 1_i32)).z()),
        ),
        (Handle::add(points, 2_i32)).z(),
    );
    (v).set_z(fp::fadds(
        (Handle::add(points, 0_i32)).z(),
        (fp::fmadds(c, fp::fmuls(var1, c), fp::fmuls(var2, c))),
    ));
    return v;
}

pub fn lbVector_EulerAnglesFromONB<'a>(
    ctx: &'a Ctx,
    result_angles: Vec<'a>,
    a: Vec<'a>,
    b: Vec<'a>,
    c: Vec<'a>,
) -> Vec<'a> {
    let __frame = ctx.stack_frame(0x28);
    let mut result_angles = result_angles;
    let mut a = a;
    let mut b = b;
    let mut c = c;
    if ((b).z() == fp::fneg(1.0)) || ((b).z() == 1.0) {
        if (b).z() == fp::fneg(1.0) {
            (result_angles).set_y(1.5707963705062866);
            (result_angles).set_x(fns::atan2f(ctx, (c).x(), (c).y()));
        } else {
            (result_angles).set_y(fp::fneg(1.5707963705062866));
            (result_angles).set_x(fns::atan2f(ctx, fp::fneg((c).x()), (c).y()));
        }
        (result_angles).set_z(0.0);
    } else {
        (result_angles).set_y(fns::asinf(ctx, fp::fneg((b).z())));
        (result_angles).set_x(fns::atan2f(ctx, (c).z(), (a).z()));
        (result_angles).set_z(fns::atan2f(ctx, (b).y(), (b).x()));
    }
    return result_angles;
}

pub fn lbVector_EulerAnglesFromPartialONB<'a>(
    ctx: &'a Ctx,
    result_angles: Vec<'a>,
    a: Vec<'a>,
    c: Vec<'a>,
) -> Vec<'a> {
    let __frame = ctx.stack_frame(0x38);
    let b: Vec<'a> = frame_at(ctx, &__frame, 0x0);
    let mut result_angles = result_angles;
    let mut a = a;
    let mut c = c;
    fns::PSVECCrossProduct(ctx, c, a, b);
    let _ = inl_lbVector_Normalize_unfused(ctx, b);
    let _ = inl_lbVector_EulerAnglesFromONB_unfused(ctx, result_angles, a, b, c);
    return result_angles;
}

